if (tx.is_coinbase())
{
    for (const auto& in: *ins)
        if (!store_.point.put(ptr, ins_fk++,
            table::point::compose(in->point()), table::point::record{}))
            return error::tx_point_put;
}
else
{
    // Write all table elements (row not linked).
    auto fk = ins_fk;
    for (const auto& in: *ins)
        if (!store_.point.set(ptr, fk++,
            table::point::compose(in->point()), table::point::record{}))
            return error::tx_point_set;

    // Exclusive search and index commit.
    std::unique_lock lock{ mutex_ };

